const initials=(name="")=>name.trim().split(/\s+/).filter(Boolean).slice(0,2).map((x)=>x[0]).join("").toUpperCase()||"AU";
const dateText=(date?:string|null)=>date?new Date(date+"T00:00:00").toLocaleDateString(undefined,{month:"short",day:"numeric",year:"numeric"}):"No deadline";
const formCode=(type:FormType)=>({student:"FORM A",department_head:"FORM B",peer:"FORM C",self:"FORM D"}[type]);

function BrandMark(){return <div className="brand-mark" aria-label="AUPES mark"><span>A</span><i/><b>U</b></div>}
function Brand({light=false}:{light?:boolean}){return <div className={cx("brand",light&&"brand-light")}><BrandMark/><div><strong>AUPES</strong><span>AMBO UNIVERSITY</span></div></div>}
function Button({children,onClick,type="button",variant="primary",disabled,className=""}:{children:React.ReactNode;onClick?:()=>void;type?:"button"|"submit";variant?:"primary"|"outline"|"ghost";disabled?:boolean;className?:string}){return <button type={type} disabled={disabled} onClick={onClick} className={cx("btn","btn-"+variant,className)}>{children}</button>}
function Avatar({name}:{name:string}){return <span className="avatar">{initials(name)}</span>}
function Notice({notice,onClose}:{notice:Notice;onClose?:()=>void}){if(!notice)return null;return <div className={cx("notice","notice-"+notice.type)}>{notice.type==="success"?<CheckCircle2 size={17}/>:notice.type==="error"?<CircleHelp size={17}/>:<ShieldCheck size={17}/>}<span>{notice.text}</span>{onClose&&<button onClick={onClose} className="notice-close" aria-label="Dismiss"><X size={15}/></button>}</div>}
function Loading({label="Loading your workspace…"}:{label?:string}){return <div className="loading-screen"><BrandMark/><LoaderCircle size={21} className="spin"/><span>{label}</span></div>}

function PublicLink({to,navigate,children,className="",onAfterNavigate}:{to:string;navigate:(to:string)=>void;children:React.ReactNode;className?:string;onAfterNavigate?:()=>void}){
 return <a href={to} className={className} onClick={e=>{if(e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;e.preventDefault();navigate(to);onAfterNavigate?.();}}>{children}</a>;
}
const PUBLIC_LINKS=[{to:"/about",label:"About AUPES"},{to:"/how-it-works",label:"How it works"},{to:"/scoring",label:"Scoring"},{to:"/privacy",label:"Privacy"},{to:"/contact",label:"Contact"}];
function PublicHeader({route,navigate}:{route:string;navigate:(to:string)=>void}){
 const {theme,setTheme,language,setLanguage,t}=useAppSettings();
 const [menuOpen,setMenuOpen]=useState(false);const [settingsOpen,setSettingsOpen]=useState(false);
 const closeMenu=()=>setMenuOpen(false);
 const links=[{to:"/",label:t("Home")},{to:"/about",label:t("About")},{to:"/academics",label:t("Academics")},{to:"/research",label:t("Research")},{to:"/news",label:t("News")},{to:"/contact",label:t("Contact")}];
 return <header className="site-nav public-header">
  <div className="nav-island nav-brand-island"><PublicLink to="/" navigate={navigate} className="university-brand-link"><span className="university-logo-box"><img src="/images/logo.png" alt="Ambo University logo" onError={e=>{e.currentTarget.style.display="none"}}/><span className="logo-fallback"><GraduationCap size={27}/></span></span></PublicLink></div>
  <button className="public-menu-toggle icon-btn" type="button" aria-label={menuOpen?t("Close navigation"):t("Open navigation")} aria-expanded={menuOpen} onClick={()=>setMenuOpen(v=>!v)}><Menu size={20}/></button>
  <div className="nav-island nav-tools-island"><div className="settings-control"><button className="nav-settings-button" type="button" aria-label={t("Settings")} aria-expanded={settingsOpen} title={t("Settings")} onClick={()=>setSettingsOpen(v=>!v)}><Settings size={17}/></button>{settingsOpen&&<div className="settings-popover" role="dialog" aria-label={t("Site settings")}><div className="settings-popover-heading"><Settings size={15}/><strong>{t("Site settings")}</strong></div><div className="settings-section-label">{t("Appearance")}</div><div className="settings-option-row"><button type="button" className={cx("settings-option",theme==="light"&&"settings-option-active")} aria-pressed={theme==="light"} onClick={()=>setTheme("light")}><Sun size={15}/>{t("Light")}</button><button type="button" className={cx("settings-option",theme==="dark"&&"settings-option-active")} aria-pressed={theme==="dark"} onClick={()=>setTheme("dark")}><Moon size={15}/>{t("Dark")}</button></div><label className="settings-language-label"><span><Languages size={15}/>{t("Language")}</span><select value={language} onChange={e=>setLanguage(e.target.value as LanguageCode)} aria-label={t("Choose a language")}><option value="en">English</option><option value="am">አማርኛ · Amharic</option><option value="om">Afaan Oromoo · Afaan Oromo</option><option value="ti">ትግርኛ · Tigrinya</option></select></label><p className="settings-hint">{t("Changes apply immediately.")}</p></div>}</div><span className="nav-action-divider"/><PublicLink to="/sign-in" navigate={navigate} className="navbar-signin" onAfterNavigate={closeMenu}><UserRound size={16}/><span>{t("Sign in")}</span></PublicLink></div>
  <button type="button" className={cx("mobile-nav-scrim",menuOpen&&"mobile-nav-scrim-visible")} aria-label={t("Close navigation")} tabIndex={menuOpen?0:-1} onClick={closeMenu}/>
  <nav className={cx("nav-island","nav-links-island",menuOpen&&"public-nav-open")} aria-label={t("Main navigation")}>{links.map(link=><PublicLink key={link.to} to={link.to} navigate={navigate} onAfterNavigate={closeMenu} className={route===link.to?"nav-link-active":""}>{link.label}</PublicLink>)}</nav>
 </header>;
}
function PublicFooter({navigate}:{navigate:(to:string)=>void}){
 const {t}=useAppSettings();
 return <footer className="site-footer public-footer"><div className="container public-footer-top"><div className="public-footer-brand"><PublicLink to="/" navigate={navigate} className="footer-brand-link"><img className="footer-university-logo" src="/images/logo.png" alt="Ambo University logo" onError={e=>{e.currentTarget.style.display="none"}}/><span className="footer-brand-copy"><strong>AUPES</strong><small>{t("Performance Evaluation System")}</small></span></PublicLink><p>{t("A thoughtful approach to teaching evaluation, meaningful feedback and academic growth.")}</p></div><div className="public-footer-column"><b>{t("Discover")}</b><PublicLink to="/about" navigate={navigate}>{t("About AUPES")}</PublicLink><PublicLink to="/academics" navigate={navigate}>{t("Academic areas")}</PublicLink><PublicLink to="/research" navigate={navigate}>{t("Research & community")}</PublicLink><PublicLink to="/news" navigate={navigate}>{t("News & stories")}</PublicLink></div><div className="public-footer-column"><b>{t("Evaluation")}</b><PublicLink to="/how-it-works" navigate={navigate}>{t("How it works")}</PublicLink><PublicLink to="/scoring" navigate={navigate}>{t("Scoring model")}</PublicLink><PublicLink to="/privacy" navigate={navigate}>{t("Privacy & confidentiality")}</PublicLink><PublicLink to="/terms-of-use" navigate={navigate}>{t("Terms of use")}</PublicLink></div><div className="public-footer-column"><b>{t("Get support")}</b><PublicLink to="/contact" navigate={navigate}>{t("Contact & support")}</PublicLink><PublicLink to="/sign-in" navigate={navigate}>{t("Sign in to AUPES")}</PublicLink><PublicLink to="/how-it-works" navigate={navigate}>{t("Evaluation guide")}</PublicLink></div></div><div className="container public-footer-bottom"><span>© {new Date().getFullYear()} AUPES · {t("Ambo University Performance Evaluation System")}</span><span><ShieldCheck size={13}/> Role-aware access · {t("Responsible evaluation")}</span></div></footer>;
}
